q = 3329

def compress_reference(x, d):
    return ((x << d) + q // 2) // q % (2 ** d)                       # exact: round(2^d x / q) mod 2^d, using an integer DIVISION by q

# the division instruction is the problem on some processors: its running time depends on the operands, and here the dividend is secret-derived.
# The remedy is to replace the division by a multiplication with a precomputed constant and a shift, which takes the same time for every input.
def find_constants(d):
    found = []
    for shift in range(24, 40):
        for constant in ((1 << shift) // q, (1 << shift) // q + 1):
            if all((((x << d) * constant + (1 << (shift - 1))) >> shift) % (2 ** d) == compress_reference(x, d) for x in range(q)):
                found.append((constant, shift))
    return found

print(f"{'d':>3} {'a division-free replacement that is exact for all 3,329 inputs (constant, shift)':<80}")
valid = {}
for d in (1, 4, 5, 10, 11):
    options = find_constants(d)
    valid[d] = options
    print(f"{d:>3} {str(options[:3]) if options else 'none found in the searched range':<80}")
print()
common = [o for o in valid[10] if all(o in valid[d] for d in (1, 4, 5, 10, 11))]
print("a single (constant, shift) pair that works for every d:", common[:3] if common else "none")

# a plausible-looking but WRONG constant: this is the kind of change that passes casual tests
wrong_constant, wrong_shift = (1 << 28) // q - 5, 28
mismatches = {d: sum((((x << d) * wrong_constant + (1 << (wrong_shift - 1))) >> wrong_shift) % (2 ** d) != compress_reference(x, d) for x in range(q)) for d in (1, 4, 5, 10, 11)}
print("a constant that is off by 5 gives wrong results for these numbers of inputs:", mismatches)
print("exhaustive testing over the whole input range (only 3,329 values) is cheap here, and is the right way to validate any replacement of a division")

# the shape of the leak, modelled: a division whose cost grows with the number of significant bits of the dividend (a simplified model, not a measurement)
def division_cost_model(dividend):
    return 1 + dividend.bit_length() // 8
costs = {d: sorted({division_cost_model(x << d) for x in range(q)}) for d in (4, 10)}
print("modelled division cost levels over the inputs 0..3328 shifted by d (4, 10):", costs, "-> different inputs, different cost: the secret-dependent value shows in the timing")
print("the multiplication-based version has one cost level for all inputs")
